// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceDeviceDiscovererEventHandler {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // This creates 1-element array, since this seems to be the only way to construct a const
    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceDeviceDiscovererEventHandler] = [UniffiVTableCallbackInterfaceDeviceDiscovererEventHandler(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeDeviceDiscovererEventHandler.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface DeviceDiscovererEventHandler: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeDeviceDiscovererEventHandler.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface DeviceDiscovererEventHandler: handle missing in uniffiClone")
            }
        },
        deviceAvailable: { (
            uniffiHandle: UInt64,
            deviceInfo: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeDeviceDiscovererEventHandler.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.deviceAvailable(
                     deviceInfo: try FfiConverterTypeDeviceInfo_lift(deviceInfo)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        deviceRemoved: { (
            uniffiHandle: UInt64,
            deviceName: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeDeviceDiscovererEventHandler.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.deviceRemoved(
                     deviceName: try FfiConverterString.lift(deviceName)
                )
            }

            
            let writeReturn = { () }
